import pyomo.environ as pyo

DATA = {
    "presses": ["four_color", "two_color"],
    "resources": ["steel_rollers", "gear_cutting", "polishing"],
    # per-unit resource usage: usage[press][resource]
    "usage": {
        "four_color": {"steel_rollers": 16, "gear_cutting": 30, "polishing": 8},
        "two_color":  {"steel_rollers": 8,  "gear_cutting": 12, "polishing": 3},
    },
    # weekly resource availability
    "availability": {
        "steel_rollers": 100,
        "gear_cutting": 160,
        "polishing": 40,
    },
    # profit per unit (DM)
    "profit": {
        "four_color": 24000,
        "two_color": 10000,
    },
    # minimum weekly production per press type (market presence)
    "min_production": {
        "four_color": 2,
        "two_color": 2,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.P = pyo.Set(initialize=d["presses"])
    model.R = pyo.Set(initialize=d["resources"])

    # Decision variables: integer number of presses produced per week
    model.production = pyo.Var(model.P, within=pyo.NonNegativeIntegers)

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Resource capacity constraints (one per resource)
    def capacity_rule(m, r):
        return sum(d["usage"][p][r] * m.production[p] for p in m.P) <= d["availability"][r]
    model.capacity = pyo.Constraint(model.R, rule=capacity_rule)

    # Minimum production constraints (market presence)
    def min_prod_rule(m, p):
        return m.production[p] >= d["min_production"][p]
    model.min_production = pyo.Constraint(model.P, rule=min_prod_rule)

    return model
